"""T-005 r7: export the hard-limit strides to the v5 ladder (rows below the last) + main file (the last row alone), schema gait_reference_opt@v2, via Tools/GaitOpt/export_reference_v2.py.
Usage (project root): export_ladder_r7.py [--tol 1e-5] [--frame f.json] [--suffix v5] stem1 stem2 ... stemN   (stems of Tools/GaitOpt/out/r7/<stem>.json, ascending Froude; N >= 2)
A stride whose max dynamics / equality / inequality residuals are <= tol is exported as FEASIBLE (the solver verdict string is only 'NOT CONVERGED' when trust-constr stopped on the iteration limit
or a stale mu_eff), otherwise the export stops. Writes Assets/Game/Config/Mech/gait_reference_qp_ladder_<suffix>.json and gait_reference_qp_<suffix>.json."""
import json, pathlib, subprocess, sys, tempfile, os
args = sys.argv[1:]; tol = 1e-5; suffix = 'v5'; frame = None
while args and args[0].startswith('--'):
    k = args.pop(0)
    if k == '--tol': tol = float(args.pop(0))
    elif k == '--suffix': suffix = args.pop(0)
    elif k == '--frame': frame = args.pop(0)
ROOT = pathlib.Path.cwd(); O = ROOT / 'Tools/GaitOpt/out/r7'; OUTD = ROOT / 'Assets/Game/Config/Mech'
env = dict(os.environ);
if frame: env['R7_FRAME'] = frame
def run(stem):
    d0 = json.load(open(O / (stem + '.json'))); s = d0['summary']
    res = max(s['max_dyn_residual'], s['max_eq_violation'], s['max_ineq_violation']) if 'max_dyn_residual' in s else max(s['max_eq_violation'], s['max_ineq_violation'])
    if res > tol: raise SystemExit(f'{stem}: residual {res:.2e} > tol {tol}')
    src = O / ('_exp_' + stem + '.json'); s['verdict'] = 'FEASIBLE'; s['export_tol'] = tol; json.dump(d0, open(src, 'w'))
    t = pathlib.Path(tempfile.mkstemp(suffix='.json')[1]); subprocess.run([sys.executable, 'Tools/GaitOpt/export_reference_v2.py', str(src), str(t)], check=True, env=env)
    d = json.loads(t.read_text()); t.unlink(); src.unlink(); d['rows'][0]['source_file'] = stem + '.json'; return d
ds = [run(s) for s in args]; rows = [d['rows'][0] for d in ds]
for a, b in zip(rows, rows[1:]): assert a['fr'] < b['fr'], 'rows must ascend in Froude'
base = ds[0]; lad = json.loads(json.dumps(base)); lad['rows'] = rows[:-1]
lad['notes'] = (f"Round-7 ladder ({suffix}): flat-foot strides re-optimised under hard limits (step time <= 3 s, CoP in [heel + 1.5, toe - 2.5] m, F_z <= 1.5 W, hip z >= 36 m, flat touchdown, rear foot flat through a "
                f"0.2 T double support); rows {[round(r['fr'], 3) for r in rows[:-1]]}; generated by evidence/T-005/round7/scripts/export_ladder_r7.py; do not edit by hand.")
lad['source']['files'] = [r['source_file'] for r in rows[:-1]]; lad['source']['verdicts'] = [f"{r['source_file']}: {r['verdict']}, fr {r['fr']}" for r in rows[:-1]]
(OUTD / f'gait_reference_qp_ladder_{suffix}.json').write_text(json.dumps(lad, indent=1))
tgt = json.loads(json.dumps(ds[-1])); tgt['notes'] = f"Round-7 target row ({suffix}) Fr {rows[-1]['fr']}, same schema as gait_reference_qp.json; generated by export_ladder_r7.py; do not edit by hand."
(OUTD / f'gait_reference_qp_{suffix}.json').write_text(json.dumps(tgt, indent=1))
print('ladder', [(round(r['fr'], 3), round(r['step_time_s'], 2), round(r['step_length_m'], 1)) for r in rows[:-1]], 'main', (round(rows[-1]['fr'], 3), round(rows[-1]['step_time_s'], 2), round(rows[-1]['step_length_m'], 1)))
